async function flaky() {
  throw new Error('boom');
}

// BUG: rejection is unhandled
function broken() {
  try {
    flaky(); // returns a Promise — does not throw synchronously
  } catch (err) {
    console.log('never runs', err);
  }
}

// FIX:
async function fixed() {
  try {
    await flaky();
  } catch (err) {
    console.log('caught', err.message);
  }
}

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled rejection at:', promise, 'reason:', reason);
  // log to observability — do not assume the process is healthy
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  // graceful shutdown — close server, flush logs, then exit
  process.exit(1);
});

// Express route — still catch per request:
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await loadUser(req.params.id);
    res.json(user);
  } catch (err) {
    next(err); // forward to error middleware
  }
});

window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled promise rejection:', event.reason);
  event.preventDefault(); // may suppress default console noise — still fix the root cause
});

function fireAndForget() {
  fetch('/api/metrics').then(r => {
    if (!r.ok) throw new Error(`metrics ${r.status}`);
  }); // missing .catch — triggers unhandledrejection if fetch fails
}

const ids = ['a', 'b', 'c'];

// BUG: rejections inside async callback are unhandled
ids.forEach(async (id) => {
  const row = await loadRow(id); // if this throws, outer try cannot catch
  processRow(row);
});

// FIX: collect promises and handle once
async function processAll() {
  await Promise.all(ids.map(async (id) => {
    const row = await loadRow(id);
    processRow(row);
  }));
}
